def la_nguyen_to(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True


a, b = map(int, input().split())
ket_qua = []
for x in range(a, b + 1):
    if la_nguyen_to(x):
        ket_qua.append(str(x))
if len(ket_qua) == 0:
    print("KHONG_CO")
else:
    print(" ".join(ket_qua))

def ucln(x, y):
    x = abs(x)
    y = abs(y)
    while y != 0:
        x, y = y, x % y
    return x


a, b = map(int, input().split())
if a == 0:
    print("0/1")
else:
    if b < 0:
        a = -a
        b = -b
    g = ucln(a, b)
    print(f"{a // g}/{b // g}")

