def manh(mk):
    if len(mk) < 8:
        return False
    co_hoa = False
    co_thuong = False
    co_so = False
    for c in mk:
        if c.isupper():
            co_hoa = True
        elif c.islower():
            co_thuong = True
        elif c.isdigit():
            co_so = True
    return co_hoa and co_thuong and co_so


